UPDATE payment
   SET tid = #{tid},
       updated_at = #{now}
 WHERE payment_id = #{paymentId}
   AND status = 'READY'

UPDATE payment
   SET status = 'PAID',
       paid_at = #{paidAt},
       updated_at = #{now}
 WHERE payment_id = #{paymentId}
   AND status = 'READY'

UPDATE payment
   SET status = 'FAILED',
       fail_reason = #{failReason},
       updated_at = #{now}
 WHERE payment_id = #{paymentId}
   AND status = 'READY'

